std::span<const Language> all_languages() { return languages; }

const Language* find_language(std::string_view code) {
  if (code == "ka") { code = "kat"; }
  if (code == "arz") { code = "ar"; }
  for (const auto& language : languages) {
    if (language.code == code) { return &language; }
  }
  return nullptr;
}

